solution.solution.cpp:
int sumTo(int n)
{
    int total{ 0 };
    for (int i{ 1 }; i <= n; ++i)
    {
        total += i;
    }
    return total;
}

unitTests:
TEST("small sums") { CHECK_EQ(sumTo(1), 1); CHECK_EQ(sumTo(4), 10); }
TEST("one hundred") { CHECK_EQ(sumTo(100), 5050); }
TEST("nothing to add") { CHECK_EQ(sumTo(0), 0); CHECK_EQ(sumTo(-5), 0); }

